import { Carousel } from '@absoluteui/components/carousel';
import { Card } from '@absoluteui/components/card';

const slides = [
  ['Spring sale', '20% off garden furniture until Sunday.'],
  ['New arrivals', 'The summer collection is here.'],
  ['Free delivery', 'On every order over 50 EUR.'],
].map(([title, content]) => {
  const host = document.createElement('div');
  Card.create(host, { title: title ?? '', content: content ?? '' });
  return { content: host, label: title ?? '' };
});
const host = document.createElement('section');
document.body.append(host);
Carousel.create(host, { label: 'Featured', slides, loop: true });

import { Carousel } from '@absoluteui/components/carousel';

const host = document.createElement('section');
document.body.append(host);
// Rotation pauses on hover and focus, and does not start for users who prefer reduced motion.
Carousel.create(host, {
  label: 'Announcements',
  autoplay: 6000,
  loop: true,
  slides: [
    { content: 'The office is closed on Monday for the public holiday.' },
    { content: 'Benefits enrollment closes on the 30th.' },
    { content: 'Welcome to the 12 people who joined this month.' },
  ],
});
